import {copy,locale,resultRows,randomId} from './model.js';
const params=new URLSearchParams(location.search),lang=locale(params.get('lang')),t=copy[lang],$=id=>document.getElementById(id);
document.documentElement.lang=lang;document.title=t.title+' · Seoul Beauty';document.querySelectorAll('[data-copy]').forEach(el=>el.textContent=t[el.dataset.copy]);$('catalog-search').placeholder=t.search;$('catalog-search').setAttribute('aria-label',t.search);$('catalog-source').setAttribute('aria-label',t.find);$('catalog-brand').setAttribute('aria-label',t.brand);
$('catalog-market').options[0].textContent=lang==='ko'?'한국':'Korea';$('catalog-market').options[1].textContent=lang==='ko'?'미국':'United States';
const other=new URL(location.href);other.searchParams.set('lang',lang==='ko'?'en':'ko');$('language').href=other.pathname+other.search;$('language').textContent=lang==='ko'?'English':'한국어';
if(params.get('test')==='1')$('testflag').textContent=t.test;
$('catalog-market').value=lang==='ko'?'KR':'US';
const run=randomId(),viewed=new Set();
let page=0,hasMore=false,busy=false,loading=false,available=false,selected=null,current=null,skip=false,readVersion=0,catalogVersion=0,retryAction=null,searchTimer;
function notify(text,retry=null){$('notice').textContent=text;retryAction=retry;$('retry').classList.toggle('hide',!retry);}
$('retry').onclick=()=>retryAction?.();
function controls(){document.querySelectorAll('button,input,select,textarea').forEach(el=>{el.disabled=busy;});$('catalog-prev').disabled=busy||page===0;$('catalog-next').disabled=busy||!hasMore;$('save-note').disabled=busy||!current?.mine;document.querySelectorAll('[data-choice]').forEach(el=>el.disabled=busy||loading||!available||!selected);}
function resetResults(){for(const id of ['followup','results','note-box'])$(id).classList.add('hide');$('note').value='';current=null;skip=false;document.querySelectorAll('[data-choice]').forEach(el=>el.setAttribute('aria-pressed','false'));}
async function request(product,body){const q=new URLSearchParams({product,...(params.get('test')==='1'?{test:'1'}:{})});const r=await fetch('/api/owned-poll?'+q,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{cache:'no-store'});if(!r.ok)throw Object.assign(Error('Request failed'),{status:r.status});return r.json();}
function telemetry(event,product=selected?.id){if(!product)return;request(product,{event,id:randomId(),run}).catch(()=>{});}
function image(element,url,fallback){element.hidden=false;fallback?.classList.add('hide');element.onerror=()=>{element.hidden=true;fallback?.classList.remove('hide');};if(url&&(/^(https:\/\/|\/beauty-play\/assets\/)/).test(url))element.src=url;else{element.hidden=true;fallback?.classList.remove('hide');}}
async function selectProduct(p){if(busy)return;const version=++readVersion;selected=p;resetResults();loading=true;controls();$('product').classList.remove('hide');$('brand').textContent=p.brand;$('name').textContent=p.name;$('image').alt=p.name;image($('image'),p.image,$('image-fallback'));
 $('option').textContent='';
 const url=new URL(location.href);url.searchParams.set('product',p.id);url.searchParams.set('lang',lang);history.replaceState(null,'',url.pathname+url.search);notify(t.loading);
 try{const data=await request(p.id);if(version!==readVersion)return;available=true;selected={...p,...data.productInfo};skip=!!data.mine;const option=data.productInfo?.options?.find(o=>o.id===params.get('option'));$('option').textContent=params.get('product')===p.id&&option?t.option+': '+option.label:'';render(data);notify('');if(!viewed.has(p.id)){telemetry('view',p.id);if(viewed.size)telemetry('explore',p.id);viewed.add(p.id);}}catch(e){if(version===readVersion){available=false;notify(e.status===404?t.unavailable:t.loadFailed,()=>selectProduct(p));}}finally{if(version===readVersion){loading=false;controls();}}
}
function bars(target,labels,counts){target.replaceChildren();for(const row of resultRows(labels,counts)){const node=document.createElement('div');node.className='result';const line=document.createElement('div');line.className='line';const label=document.createElement('span');label.textContent=row.label;const count=document.createElement('span');count.textContent=row.count+t.unit;line.append(label,count);const track=document.createElement('div');track.className='track';const fill=document.createElement('div');fill.className='fill';fill.style.width=row.percent+'%';track.append(fill);node.append(line,track);target.append(node);}}
function render(data){current=data;document.querySelectorAll('[data-choice]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.choice===data.mine)));const done=!!data.mine&&(!!data.mineFollowup||skip);$('followup').classList.toggle('hide',!data.mine||done);$('results').classList.toggle('hide',!done);$('note-box').classList.toggle('hide',!done);
 if(data.mine&&!done){const cfg=t.followups[data.mine];$('follow-title').textContent=cfg.title;$('follow-choices').replaceChildren();for(const [id,label]of Object.entries(cfg.options)){const b=document.createElement('button');b.type='button';b.textContent=label;b.onclick=()=>submit(data.mine,id);$('follow-choices').append(b);}}
 if(done){$('total').textContent=data.total+t.responses+(data.total<=1?' · '+t.noOthers:'');bars($('bars'),t.labels,data.counts);$('related-results').replaceChildren();if(data.mineFollowup){const h=document.createElement('h3');h.textContent=t.followResults;const box=document.createElement('div');bars(box,t.followups[data.mine].options,data.followupCounts?.[data.mine]);$('related-results').append(h,box);}}
 controls();
}
async function submit(choice,followup,note){if(busy||!available||!selected)return;const product=selected.id;busy=true;readVersion++;controls();notify(t.saving);try{const data=await request(product,{choice,followup,option:params.get('product')===product?(selected.options?.find(o=>o.id===params.get('option'))?.id||null):null,...(note!==undefined?{note}:{})});render(data);notify(t.saved);}catch{notify(t.failed,()=>submit(choice,followup,note));}finally{busy=false;controls();}}
for(const[id,label]of Object.entries(t.labels)){const b=document.createElement('button');b.type='button';b.textContent=label;b.dataset.choice=id;b.setAttribute('aria-pressed','false');b.onclick=()=>{skip=false;submit(id,null);};$('choices').append(b);}
$('skip-follow').onclick=()=>{if(!current)return;skip=true;telemetry('skip_followup');render(current);};$('save-note').onclick=()=>{if(current?.mine)submit(current.mine,current.mineFollowup,$('note').value.trim());};
async function browse(){if(busy)return;const version=++catalogVersion;const q=new URLSearchParams({catalog:'1',source:$('catalog-source').value,q:$('catalog-search').value,brand:$('catalog-brand').value,page:String(page),market:$('catalog-market').value});$('catalog-hint').classList.toggle('hide',$('catalog-source').value!=='catalog');
 try{const r=await fetch('/api/owned-poll?'+q,{cache:'no-store'});if(!r.ok)throw Object.assign(Error('Catalog failed'),{status:r.status});const data=await r.json();if(version!==catalogVersion)return;available=true;hasMore=data.hasMore;const old=$('catalog-brand').value;$('catalog-brand').replaceChildren();for(const brand of ['',...data.brands,...new Set(data.products.map(p=>p.brand)),...(old?[old]:[])].filter((x,i,a)=>a.indexOf(x)===i)){const opt=document.createElement('option');opt.value=brand;opt.textContent=brand||t.brand;$('catalog-brand').append(opt);}$('catalog-brand').value=old;$('catalog-list').replaceChildren();for(const p of data.products){const b=document.createElement('button'),img=document.createElement('img'),label=document.createElement('span');b.type='button';img.alt='';image(img,p.image);label.textContent=p.brand+' · '+p.name;b.append(img,label);b.onclick=()=>selectProduct(p);$('catalog-list').append(b);}$('catalog-count').textContent=(page+1)+(hasMore?' +':'');if(!data.products.length)$('catalog-list').textContent=t.empty;
 if(!selected&&data.products[0])await selectProduct(data.products[0]);
 }catch(e){if(version!==catalogVersion)return;available=false;notify(e.status===404?t.unavailable:t.loadFailed,browse);}finally{if(version===catalogVersion)controls();}
}
$('catalog-prev').onclick=()=>{if(page>0){page--;browse();}};$('catalog-next').onclick=()=>{if(hasMore){page++;browse();}};
for(const id of ['catalog-source','catalog-brand','catalog-market'])$(id).onchange=()=>{page=0;if(id!=='catalog-brand')$('catalog-brand').value='';browse();};$('catalog-search').oninput=()=>{clearTimeout(searchTimer);page=0;searchTimer=setTimeout(browse,200);};
async function start(){controls();if(params.get('product')){try{const data=await request(params.get('product'));if(!selected&&data.productInfo)await selectProduct(data.productInfo);}catch(e){notify(e.status===404?t.unavailable:t.loadFailed);}}await browse();}
start();
